+func carrySectionFactsOntoRealised(realised []interface{}, proposed interface{}) ([]interface{}, int, []string) {
+	pl, _ := proposed.([]interface{})
+	if len(pl) == 0 || len(realised) == 0 {
+		return realised, 0, nil
+	}
+	// name -> queue of assignments, in emission order
+	type pendingAssignment struct { name string; facts []interface{}; used bool }
+	var pending []pendingAssignment
+	byName := make(map[string][]int)
+	for _, entry := range pl {
+		obj, ok := entry.(map[string]interface{}); if !ok { continue }
+		name, ok := sectionEntryName(obj); if !ok { continue }
+		// absent key == unscoped, [] == deliberately factless: only the second carries
+		facts, ok := obj["facts"].([]interface{}); if !ok { continue }
+		byName[name] = append(byName[name], len(pending))
+		pending = append(pending, pendingAssignment{name: name, facts: facts})
+	}
+	if len(pending) == 0 { return realised, 0, nil }
+
+	merged := make([]interface{}, len(realised))
+	carried := 0
+	for i, entry := range realised {
+		merged[i] = entry
+		name, ok := sectionEntryName(entry); if !ok { continue }
+		idx := -1
+		for _, c := range byName[name] { if !pending[c].used { idx = c; break } }
+		if idx < 0 { continue }
+		pending[idx].used = true
+		// clone an object entry rather than replace it: its other keys are not ours to drop
+		if src, isObj := entry.(map[string]interface{}); isObj {
+			clone := make(map[string]interface{}, len(src)+1)
+			for k, v := range src { clone[k] = v }
+			clone["facts"] = pending[idx].facts
+			merged[i] = clone
+		} else {
+			merged[i] = map[string]interface{}{"name": name, "facts": pending[idx].facts}
+		}
+		carried++
+	}
+	var unmatched []string
+	for _, p := range pending { if !p.used { unmatched = append(unmatched, p.name) } }
+	if carried == 0 { return realised, 0, unmatched }
+	return merged, carried, unmatched
+}
